export function classifyIntent(text) {
  if (text === undefined || text === null) return [];
  if (typeof text !== 'string') return ['invalid_intent_text'];
  const low = text
    .normalize('NFKC')
    .replace(/[​-‍﻿]/g, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .toLowerCase();
  return FORBIDDEN_INTENT_RULES
    .filter(rule => rule.re.test(low))
    .map(rule => rule.id);
}


